"""Regression tests for the Chronos and Chronos-Bolt forecaster."""

import numpy as np
import pandas as pd
import pytest
from skbase.utils.dependencies import _check_soft_dependencies

from sktime.datasets import load_airline
from sktime.forecasting.chronos import ChronosForecaster
from sktime.tests.test_switch import run_test_for_class

if _check_soft_dependencies("torch", severity="none"):
    import torch

# Reference forecasts were generated by calling amazon-science/chronos-forecasting's
# ChronosPipeline/ChronosBoltPipeline directly, see scripts/golden-chronos.py.
#
# torch_dtype is forced to float32 (instead of the bfloat16 default) since
# bfloat16 has only ~3 significant decimal digits: cross-platform matmul
# reduction-order differences (x86 vs ARM, different thread counts) are large
# enough to occasionally flip which sample lands in a median/order-statistic,
# which is not a real implementation discrepancy but hardware-dependent noise.
_CHRONOS_REFERENCE_CASES = [
    pytest.param(
        "amazon/chronos-t5-tiny",
        {"seed": 0},
        [
            465.13885,
            383.83408,
            332.78226,
        ],
        id="chronos-t5-tiny-seed0-default-num-samples",
    ),
    pytest.param(
        "amazon/chronos-t5-tiny",
        {"seed": 42, "config": {"num_samples": 20}},
        [
            467.02966,
            386.6703,
            332.78226,
        ],
        id="chronos-t5-tiny-seed42-num-samples20",
    ),
    pytest.param(
        "amazon/chronos-bolt-tiny",
        {},
        [
            517.19104,
            432.6267,
            411.72766,
        ],
        id="chronos-bolt-tiny",
    ),
]


@pytest.mark.skipif(
    not run_test_for_class(ChronosForecaster),
    reason="run test only if softdeps are present and incrementally (if requested)",
)
@pytest.mark.parametrize(
    "model_path,forecaster_kwargs,expected_head",
    _CHRONOS_REFERENCE_CASES,
)
def test_chronos_airline_predictions_match_source_reference(
    model_path, forecaster_kwargs, expected_head
):
    """Chronos/Chronos-Bolt predictions match original outputs."""
    y = load_airline()
    fh = np.arange(1, 17)
    y_train = y.iloc[: -len(fh)]
    forecaster_kwargs = dict(forecaster_kwargs)
    config = {"torch_dtype": torch.float32, **forecaster_kwargs.pop("config", {})}
    forecaster = ChronosForecaster(
        model_path=model_path,
        use_source_package=False,
        config=config,
        **forecaster_kwargs,
    )

    y_pred = forecaster.fit(y_train, fh=fh).predict(fh=fh)

    np.testing.assert_allclose(
        y_pred.iloc[:3].to_numpy().ravel(),
        np.asarray(expected_head, dtype=np.float32),
        rtol=1e-5,
        atol=1e-4,
    )


@pytest.mark.skipif(
    not run_test_for_class(ChronosForecaster),
    reason="run test only if softdeps are present and incrementally (if requested)",
)
def test_chronos_bolt_long_prediction_length():
    """Chronos-Bolt supports prediction horizons longer than its native length."""
    y = pd.Series(range(128), dtype=float)
    fh = np.arange(1, 66)

    forecaster = ChronosForecaster(
        model_path="amazon/chronos-bolt-tiny",
        config={"device_map": "cpu"},
    )

    y_pred = forecaster.fit(y, fh=fh).predict()

    assert len(y_pred) == len(fh)


def _save_tiny_chronos_model(path, tokenizer_class):
    """Save a tiny randomly initialized Chronos model with the given tokenizer_class."""
    from transformers import T5Config, T5ForConditionalGeneration

    config = T5Config(
        vocab_size=32,
        d_model=8,
        d_ff=16,
        d_kv=4,
        num_layers=1,
        num_decoder_layers=1,
        num_heads=2,
        decoder_start_token_id=0,
        pad_token_id=0,
        eos_token_id=1,
    )
    config.chronos_config = {
        "tokenizer_class": tokenizer_class,
        "tokenizer_kwargs": {"low_limit": -15.0, "high_limit": 15.0},
        "context_length": 16,
        "prediction_length": 4,
        "n_tokens": 32,
        "n_special_tokens": 2,
        "pad_token_id": 0,
        "eos_token_id": 1,
        "use_eos_token": True,
        "model_type": "seq2seq",
        "num_samples": 2,
        "temperature": 1.0,
        "top_k": 5,
        "top_p": 1.0,
    }
    T5ForConditionalGeneration(config).save_pretrained(path)


@pytest.mark.skipif(
    not run_test_for_class(ChronosForecaster),
    reason="run test only if softdeps are present and incrementally (if requested)",
)
def test_chronos_tokenizer_class_from_model_config(tmp_path):
    """The tokenizer_class in the model config selects a ChronosTokenizer by name."""
    from sktime.libs.chronos.chronos import MeanScaleUniformBins

    _save_tiny_chronos_model(tmp_path, "MeanScaleUniformBins")
    forecaster = ChronosForecaster(model_path=str(tmp_path))

    y_pred = forecaster.fit(load_airline()).predict(fh=[1, 2, 3])

    assert isinstance(forecaster.model_pipeline.tokenizer, MeanScaleUniformBins)
    assert len(y_pred) == 3


@pytest.mark.skipif(
    not run_test_for_class(ChronosForecaster),
    reason="run test only if softdeps are present and incrementally (if requested)",
)
@pytest.mark.parametrize(
    "tokenizer_class",
    ["dict", "1 + 1", "(lambda **kwargs: None)"],
)
def test_chronos_tokenizer_class_is_not_evaluated(tmp_path, tokenizer_class):
    """A tokenizer_class that is not a ChronosTokenizer name is looked up, not run.

    The tokenizer_class string is read from the model config.json. It must be
    resolved as a name in the chronos module, not evaluated as a python
    expression, so that loading a model cannot execute arbitrary code.
    """
    _save_tiny_chronos_model(tmp_path, tokenizer_class)
    forecaster = ChronosForecaster(model_path=str(tmp_path))

    with pytest.raises(AttributeError):
        forecaster.fit(load_airline())
